# Entrées de l'index Torah-Box sans équivalent dans le Siddur Edot HaMizrach de Sefaria
# (à compléter par d'autres sources libres si besoin) :
#   Seli'hot (Eloul), Téhilim (livre entier : "@Psalms N|..." si besoin), Téfilot diverses,
#   Iguérèt haRamban, Kivré tsadikim, Tikoun Hocha'ana Rabba, Hatarat nédarim,
#   'Hanoukat habayit, Rituel décès & azkara, Brit Its'hak (Zohar),
#   offices complets de Tich'a béav, 'Hol hamoèd, Pourim et des jeûnes.
#   Kétoret : déjà inclus dans la prière du matin.

# ---------------------------------------------------------------------------
# 2. Récupération (avec cache local pour ne solliciter l'API qu'une fois)
# ---------------------------------------------------------------------------

def fetch_section(ref: str, cache_dir: Path, offline: bool) -> dict:
    version = "hebrew"
    if ref.startswith("@"):
        ref, _, v = ref[1:].partition("|")
        full_ref = ref
        version = v or version
    else:
        full_ref = f"{BOOK}, {ref}"
    key = full_ref + ("" if version == "hebrew" else f"__{version}")
    cache_file = cache_dir / (re.sub(r"[^\w]+", "_", key).strip("_") + ".json")
    if cache_file.exists():
        return json.loads(cache_file.read_text(encoding="utf-8"))
    if offline:
        raise FileNotFoundError(f"Pas en cache : {full_ref}")
    import requests

    url = API.format(ref=full_ref.replace(" ", "_"))
    r = requests.get(url, params={"version": version}, timeout=30,
                     headers={"User-Agent": "siddour-ebook (usage personnel)"})
    r.raise_for_status()
    data = r.json()
    if not (data.get("versions") or [{}])[0].get("text"):
        raise ValueError(f"texte vide pour {full_ref} ({version})")
    cache_dir.mkdir(parents=True, exist_ok=True)
    cache_file.write_text(json.dumps(data, ensure_ascii=False, indent=1), encoding="utf-8")
    time.sleep(0.5)  # rester poli avec l'API
    return data


def select_plan(args) -> list[dict]:
    if args.chapitres:
        wanted = [c.strip() for c in args.chapitres.split(",") if c.strip()]
        known = {c["id"] for c in PLAN}
        unknown = [w for w in wanted if w not in known]
        if unknown:
            sys.exit(f"Chapitres inconnus : {', '.join(unknown)}  (voir --liste)")
        return [c for c in PLAN if c["id"] in wanted]
    return [c for c in PLAN if args.complet or c["quotidien"]]


def flatten(text) -> list[str]:
    if isinstance(text, str):
        return [text]
    out: list[str] = []
    for t in text or []:
        out.extend(flatten(t))
    return out

# ---------------------------------------------------------------------------
# 3. Nettoyage du HTML Sefaria -> segments (texte, est_une_consigne)
# ---------------------------------------------------------------------------
TAG_RE = re.compile(r"<(/?)(\w+)[^>]*>")


def parse_paragraph(raw: str) -> tuple[str, list[tuple[str, bool]]]:
    """Retourne (type, segments). type = 'heading' | 'note' | 'text'."""
    raw = raw.replace("<br>", " ").replace("<br/>", " ").replace("<br />", " ")
    raw = re.sub(r"\{[פס]\}", "", raw)  # marqueurs de paracha du Tanakh
    segments: list[tuple[str, bool]] = []
    small_depth = 0
    pos = 0
    for m in TAG_RE.finditer(raw):
        chunk = raw[pos:m.start()]
        if chunk:
            segments.append((html.unescape(chunk), small_depth > 0))
        closing, tag = m.group(1), m.group(2).lower()
        if tag == "small":
            small_depth += -1 if closing else 1
        pos = m.end()
    if raw[pos:]:
        segments.append((html.unescape(raw[pos:]), small_depth > 0))
    segments = [(re.sub(r"\s+", " ", s), n) for s, n in segments if s.strip()]

    stripped = raw.strip()
    if re.fullmatch(r"<big>.*</big>", stripped, re.S) and "<small>" not in stripped:
        return "heading", segments
    if segments and all(n for _, n in segments):
        return "note", segments
    return "text", segments

# ---------------------------------------------------------------------------
# 4. Translittération séfarade (conventions françaises)
#    Ajuste ces tables à ton goût.
# ---------------------------------------------------------------------------
SHEVA, HATAF_SEGOL, HATAF_PATAH, HATAF_QAMATS = "ְ", "ֱ", "ֲ", "ֳ"
HIRIQ, TSERE, SEGOL, PATAH, QAMATS = "ִ", "ֵ", "ֶ", "ַ", "ָ"
HOLAM, HOLAM_HASER, QUBUTS, DAGESH = "ֹ", "ֺ", "ֻ", "ּ"
SHIN_DOT, SIN_DOT, QAMATS_QATAN, MAQAF = "ׁ", "ׂ", "ׇ", "־"

VOWELS = {
    PATAH: "a", QAMATS: "a", HATAF_PATAH: "a", HATAF_QAMATS: "o",
    TSERE: "é", SEGOL: "è", HATAF_SEGOL: "è",
    HIRIQ: "i", HOLAM: "o", HOLAM_HASER: "o", QUBUTS: "ou", QAMATS_QATAN: "o",
}
SHEVA_NA = "e"

CONSONANTS = {
    "א": "", "ג": "g", "ד": "d", "ה": "h", "ז": "z", "ח": "'h", "ט": "t",
    "י": "y", "ל": "l", "מ": "m", "ם": "m", "נ": "n", "ן": "n", "ס": "s",
    "ע": "'", "צ": "ts", "ץ": "ts", "ק": "k", "ר": "r", "ת": "t", "ו": "v",
}
SOFT_HARD = {"ב": ("v", "b"), "כ": ("kh", "k"), "ך": ("kh", "k"),
             "פ": ("f", "p"), "ף": ("f", "p")}

# Mots au cas particulier (forme consonantique -> phonétique)
EXCEPTIONS = {
    "יהוה": "Adonaï", "יי": "Adonaï", "ה'": "Hachem",
    "כל": None,  # traité plus bas (kol / kal)
}
CANTILLATION = re.compile(r"[֑-ֽֿׅ֯ׄ]")
HEB_LETTER = re.compile(r"[א-ת]")


def _split_letters(word: str) -> list[tuple[str, set[str]]]:
    letters: list[tuple[str, set[str]]] = []
    for ch in word:
        if HEB_LETTER.match(ch):
            letters.append((ch, set()))
        elif letters and "ְ" <= ch <= "ׇ":
            letters[-1][1].add(ch)
    return letters


def _vowel_of(marks: set[str]) -> str | None:
    for m in (PATAH, QAMATS, HATAF_PATAH, HATAF_QAMATS, TSERE, SEGOL, HATAF_SEGOL,
              HIRIQ, HOLAM, HOLAM_HASER, QUBUTS, QAMATS_QATAN, SHEVA):
        if m in marks:
            return m
    return None


def translit_word(word: str) -> str:
    consonants_only = "".join(c for c in word if HEB_LETTER.match(c) or c == "'")
    if consonants_only in ("יהוה", "יי", "ה'"):
        return EXCEPTIONS[consonants_only]
    letters = _split_letters(word)
    if not letters:
        return word
    if consonants_only == "כל" and QAMATS in letters[0][1]:
        return "kol"

    out: list[str] = []
    n = len(letters)
    prev_vowel: str | None = None  # dernière voyelle prononcée
    for i, (ch, marks) in enumerate(letters):
        v = _vowel_of(marks)
        last = i == n - 1
        nxt = letters[i + 1] if i + 1 < n else None

        # --- vav : holam malé (וֹ) ou chourouk (וּ)
        if ch == "ו" and v in (HOLAM, HOLAM_HASER) and i > 0 and _vowel_of(letters[i - 1][1]) is None:
            out.append("o"); prev_vowel = HOLAM; continue
        if ch == "ו" and DAGESH in marks and v is None and (i == 0 or _vowel_of(letters[i - 1][1]) is None):
            out.append("ou"); prev_vowel = QUBUTS; continue

        # --- yod mater lectionis
        if ch == "י" and v is None and DAGESH not in marks and i > 0:
            if prev_vowel in (HIRIQ, TSERE, SEGOL):
                continue  # ִי / ֵי / ֶי : yod muet
            if prev_vowel in (PATAH, QAMATS):
                if nxt and nxt[0] == "ו" and i + 1 == n - 1:
                    continue  # ָיו -> "av"
                if last:
                    out.append("ï"); continue

        # --- lettres muettes en fin de mot
        if last and v is None and ch in "אה" and not (ch == "ה" and DAGESH in marks):
            continue
        if last and v is None and ch == "ע":
            continue

        # --- consonne
        if ch in SOFT_HARD:
            soft, hard = SOFT_HARD[ch]
            cons = hard if DAGESH in marks else soft
        elif ch == "ש":
            cons = "s" if SIN_DOT in marks else "ch"
        else:
            cons = CONSONANTS.get(ch, ch)
        if ch == "ע" and i == 0:
            cons = ""

        # --- patah furtif (רוּחַ -> roua'h)
        if last and v == PATAH and ch in "חע" or (last and v == PATAH and ch == "ה" and DAGESH in marks):
            out.append("a" + cons); prev_vowel = PATAH; continue

        # --- voyelle
        if v == SHEVA:
            prev_marks = letters[i - 1][1] if i > 0 else set()
            na = (i == 0
                  or (i == 1 and out and out[0] == "ou")
                  or (SHEVA in prev_marks and not last)
                  or (DAGESH in marks and i > 0 and not last)
                  or (nxt is not None and nxt[0] == ch))
            vow = SHEVA_NA if (na and not last) else ""
        elif v is not None:
            vow = VOWELS[v]
        else:
            vow = ""
        out.append(cons + vow)
        if v is not None and v != SHEVA:
            prev_vowel = v
        elif vow:
            prev_vowel = SHEVA

    word_out = "".join(out).replace("''", "'")
    # כָּל / בְּכָל / וּבְכָל : kamats katan -> "kol"
    if len(letters) >= 2 and letters[-1][0] == "ל" and _vowel_of(letters[-1][1]) is None \
            and letters[-2][0] == "כ" and QAMATS in letters[-2][1]:
        word_out = re.sub(r"(k|kh)al$", r"\1ol", word_out)
    return word_out


def translit(text: str, capitalize: bool = True) -> str:
    text = unicodedata.normalize("NFC", text)
    text = CANTILLATION.sub("", text)
    text = text.replace(MAQAF, "-").replace("׃", ".").replace("׀", "")
    parts = re.split(r"([א-תְ-ׇ']+)", text)
    res = []
    for p in parts:
        if p and HEB_LETTER.search(p):
            res.append(translit_word(p))
        else:
            res.append(p)
    s = "".join(res)
    s = re.sub(r"\s+([,.:;])", r"\1", s)
    s = re.sub(r"\s+", " ", s).strip()
    if not capitalize:
        return s
    return s[:1].upper() + s[1:] if s else s


