CURRENT_REF = ''
_basic_instruction=instruction
_basic_load_overrides=load_rubric_overrides
_layout_translation_cache=None
def load_rubric_overrides(path):
    global _layout_translation_cache
    _basic_load_overrides(path)
    _layout_translation_cache=None

def _rubric_key(text):
    return re.sub(r'\s+([),.;:])',r'\1',plain_hebrew(text))

def instruction(text):
    global _layout_translation_cache
    key=_rubric_key(text)
    if _layout_translation_cache is None:
        _layout_translation_cache={_rubric_key(k):v for k,v in TRANSLATIONS.items()}
    lookup=_layout_translation_cache
    if key in lookup:return lookup[key]
    # Les balises <b> de la source séparaient parfois une consigne de sa citation.
    # La nouvelle mise en page les réunit sans changer leur traduction.
    citations=re.findall(r'\([^()]*\)',key)
    base=re.sub(r'\([^()]*\)','',key).strip()
    if base in lookup and citations and all(c in lookup for c in citations):
        return lookup[base]+' '+' '.join(lookup[c] for c in citations)
    if key=='בחזרת הש"ץ אומרים ברכת כהנים, אם יש יותר מכהן אחד קורא להם החזן: כהנים: הכהנים מברכים':
        return 'Pendant la répétition de l’Amida, réciter la bénédiction des Cohanim. S’il y a plusieurs Cohanim, l’officiant les appelle : « Cohanim ». Les Cohanim récitent la bénédiction :'
    return _basic_instruction(text)

_basic_split_rubric=split_rubric
def split_rubric(text):
    key=_rubric_key(text)
    if key=='בחזרת הש"ץ אומרים ברכת כהנים, אם יש יותר מכהן אחד קורא להם החזן: כהנים: הכהנים מברכים':
        word=next((w for w in text.split() if plain_hebrew(w)=='כהנים' and _is_vocalized(w)),None)
        if word:
            return [('instruction','Pendant la répétition de l’Amida, s’il y a plusieurs Cohanim, l’officiant les appelle :'),('prayer',word),('instruction','Les Cohanim récitent la bénédiction :')]
    return _basic_split_rubric(text)

